@page "/apply"
@namespace sv_122c30489d454c1fbb546b0370095a5a.Components.Pages.Apply
@using sv_122c30489d454c1fbb546b0370095a5a.Models
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="application-form">
    <h2>Job Application</h2>

    <StepIndicator CurrentStep="_currentStep" OnStepSelected="GoToStep" />

    @switch (_currentStep)
    {
        case 0:
            <PersonalInfoStep FullName="@_fullName" Email="@_email" Phone="@_phone" Address="@_address"
                              OnNext="HandlePersonalInfoNext"
                              ValidateEmail="ApplicationService.ValidateEmailAsync" />
            break;
        case 1:
            <WorkHistoryStep Entries="_workEntries" OnNext="HandleWorkHistoryNext" OnBack="GoBack" />
            break;
        case 2:
            <ReferencesStep References="_references" OnNext="HandleReferencesNext" OnBack="GoBack" />
            break;
        case 3:
            <CoverLetterStep CoverLetterText="@_coverLetter" OnNext="HandleCoverLetterNext" OnBack="GoBack" />
            break;
        case 4:
            <ReviewStep FullName="@_fullName" Email="@_email" Phone="@_phone" Address="@_address"
                        WorkEntries="_workEntries" References="_references"
                        CoverLetterText="@_coverLetter"
                        OnEditSection="GoToStep" OnBack="GoBack"
                        OnSubmit="SubmitApplication" />
            break;
    }
</div>

@code {
    private int _currentStep;
    private string _fullName = "";
    private string _email = "";
    private string _phone = "";
    private string _address = "";
    private List<WorkHistoryStep.WorkEntryModel> _workEntries = new() { new() };
    private List<ReferencesStep.ReferenceModel> _references = new() { new(), new() };
    private string _coverLetter = "";

    private void GoToStep(int step)
    {
        _currentStep = step;
    }

    private void GoBack()
    {
        if (_currentStep > 0) _currentStep--;
    }

    private void HandlePersonalInfoNext((string FullName, string Email, string Phone, string Address) data)
    {
        _fullName = data.FullName;
        _email = data.Email;
        _phone = data.Phone;
        _address = data.Address;
        _currentStep = 1;
    }

    private void HandleWorkHistoryNext(List<WorkHistoryStep.WorkEntryModel> entries)
    {
        _workEntries = entries;
        _currentStep = 2;
    }

    private void HandleReferencesNext(List<ReferencesStep.ReferenceModel> references)
    {
        _references = references;
        _currentStep = 3;
    }

    private void HandleCoverLetterNext(string coverLetter)
    {
        _coverLetter = coverLetter;
        _currentStep = 4;
    }

    private async Task<int> SubmitApplication()
    {
        var personal = new PersonalInfo(_fullName, _email, _phone, _address);
        var workHistory = new WorkHistory(_workEntries.Select(e =>
            new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description)).ToList());
        var refs = _references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
        var application = new JobApplication(personal, workHistory, refs, _coverLetter);

        return await ApplicationService.SubmitApplicationAsync(application);
    }
}

.application-form {
    max-width: 800px;
    margin: 2rem auto;
    padding: 0 1rem;
}

.application-form h2 {
    text-align: center;
    margin-bottom: 2rem;
    color: #1a1a2e;
}

/* Step Indicator */
.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 2rem;
    padding: 1rem 0;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    cursor: default;
    min-width: 80px;
}

.step.completed {
    cursor: pointer;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.875rem;
    border: 2px solid #ddd;
    background: #fff;
    color: #999;
    transition: all 0.2s;
}

.step.active .step-circle {
    background: #4361ee;
    border-color: #4361ee;
    color: #fff;
}

.step.completed .step-circle {
    background: #2ec4b6;
    border-color: #2ec4b6;
    color: #fff;
}

.step.dimmed .step-circle {
    opacity: 0.5;
}

.step-label {
    margin-top: 0.5rem;
    font-size: 0.75rem;
    color: #666;
    text-align: center;
    white-space: nowrap;
}

.step.active .step-label {
    color: #4361ee;
    font-weight: 600;
}

.step.completed .step-label {
    color: #2ec4b6;
}

.step.dimmed .step-label {
    opacity: 0.5;
}

.step-connector {
    flex: 1;
    height: 2px;
    background: #ddd;
    margin: 0 0.5rem;
    margin-bottom: 1.5rem;
    max-width: 60px;
}

.step-connector.completed {
    background: #2ec4b6;
}

/* Step Panel */
.step-panel {
    background: #fff;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    padding: 2rem;
    box-shadow: 0 2px 8px rgba(0,0,0,0.04);
}

.step-panel h3 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    color: #1a1a2e;
}

/* Form Elements */
.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.375rem;
    font-weight: 500;
    color: #333;
    font-size: 0.875rem;
}

.form-control {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 0.95rem;
    transition: border-color 0.2s;
    box-sizing: border-box;
}

.form-control:focus {
    outline: none;
    border-color: #4361ee;
    box-shadow: 0 0 0 2px rgba(67, 97, 238, 0.1);
}

.form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

.checkbox-label {
    display: inline-flex !important;
    align-items: center;
    gap: 0.5rem;
    margin-top: 0.5rem;
    font-weight: normal !important;
    cursor: pointer;
}

.checkbox-label input[type="checkbox"] {
    width: auto;
}

/* Buttons */
.step-buttons {
    display: flex;
    justify-content: space-between;
    margin-top: 2rem;
    padding-top: 1.5rem;
    border-top: 1px solid #eee;
}

.btn {
    padding: 0.6rem 1.5rem;
    border-radius: 4px;
    font-size: 0.95rem;
    font-weight: 500;
    cursor: pointer;
    border: none;
    transition: all 0.2s;
}

.btn:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-primary {
    background: #4361ee;
    color: #fff;
    margin-left: auto;
}

.btn-primary:hover:not(:disabled) {
    background: #3a56d4;
}

.btn-outline {
    background: transparent;
    border: 1px solid #ccc;
    color: #555;
}

.btn-outline:hover {
    border-color: #999;
    color: #333;
}

.btn-secondary {
    background: #f0f0f0;
    color: #333;
    border: 1px solid #ddd;
}

.btn-secondary:hover {
    background: #e4e4e4;
}

.btn-danger {
    background: #e63946;
    color: #fff;
}

.btn-danger:hover {
    background: #d62839;
}

.btn-sm {
    padding: 0.3rem 0.75rem;
    font-size: 0.8rem;
}

.btn-link {
    background: none;
    border: none;
    color: #4361ee;
    cursor: pointer;
    font-size: 0.875rem;
    text-decoration: underline;
    padding: 0;
}

.btn-link:hover {
    color: #3a56d4;
}

.btn-submit {
    padding: 0.75rem 2rem;
    font-size: 1.05rem;
}

/* Validation */
.validation-summary {
    background: #fff3f3;
    border: 1px solid #e63946;
    color: #e63946;
    padding: 0.75rem 1rem;
    border-radius: 4px;
    margin-top: 1rem;
    font-size: 0.875rem;
}

.field-error {
    color: #e63946;
    font-size: 0.8rem;
    margin-top: 0.25rem;
    display: block;
}

/* Work Entry & Reference Forms */
.work-entry-form, .reference-form {
    border: 1px solid #eee;
    border-radius: 6px;
    padding: 1.25rem;
    margin-bottom: 1rem;
    background: #fafafa;
}

.work-entry-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
}

.work-entry-header h5, .reference-form h5 {
    margin: 0;
    color: #444;
}

/* Cover Letter */
.cover-letter-textarea {
    min-height: 250px;
    resize: vertical;
}

.char-count {
    text-align: right;
    font-size: 0.8rem;
    color: #888;
    margin-top: 0.25rem;
}

.char-count.warning {
    color: #e07c00;
    font-weight: 500;
}

/* Review Step */
.review-section {
    border-bottom: 1px solid #eee;
    padding-bottom: 1.25rem;
    margin-bottom: 1.25rem;
}

.review-section:last-of-type {
    border-bottom: none;
}

.review-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.review-header h4 {
    margin: 0;
    color: #1a1a2e;
}

.review-section dl {
    display: grid;
    grid-template-columns: 120px 1fr;
    gap: 0.4rem 1rem;
    margin: 0;
}

.review-section dt {
    font-weight: 500;
    color: #666;
    font-size: 0.875rem;
}

.review-section dd {
    margin: 0;
    color: #333;
}

.review-work-entry, .review-reference {
    padding: 0.75rem 0;
    border-bottom: 1px solid #f0f0f0;
}

.review-work-entry:last-child, .review-reference:last-child {
    border-bottom: none;
}

.date-range {
    font-size: 0.85rem;
    color: #666;
}

.cover-letter-preview {
    white-space: pre-wrap;
    background: #f8f8f8;
    padding: 1rem;
    border-radius: 4px;
    font-size: 0.9rem;
    line-height: 1.6;
}

/* Confirmation */
.confirmation {
    text-align: center;
    padding: 3rem 1rem;
}

.confirmation-icon {
    width: 64px;
    height: 64px;
    border-radius: 50%;
    background: #2ec4b6;
    color: #fff;
    font-size: 2rem;
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 0 auto 1.5rem;
}

.confirmation h4 {
    color: #1a1a2e;
    margin-bottom: 0.5rem;
}

.confirmation p {
    color: #555;
}

.hint {
    color: #666;
    font-size: 0.875rem;
    margin-bottom: 1rem;
}

